#!/bin/bash
# Serial monitor script for theSpeaker (3 boards)
# Auto-generated by Embedded Generator

PORT="${1:-/dev/ttyUSB0}"
BAUD="${2:-115200}"

# Check if ESP-IDF is set up
if [ -z "$IDF_PATH" ]; then
    echo "ERROR: ESP-IDF environment not set up."
    echo "Please run: . $HOME/esp/esp-idf/export.sh"
    exit 1
fi

echo "Starting serial monitor on $PORT at $BAUD baud..."
echo "Press Ctrl+] to exit"
echo ""

idf.py -p "$PORT" -b "$BAUD" monitor
